sys_script_include.script:
var CheckCourseEnrollmentLimit = Class.create();
CheckCourseEnrollmentLimit.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    hasReachedLimit: function() {
        var openedBy = this.getParameter('sysparm_opened_by');   
        var courseId = this.getParameter('sysparm_course_id');   

        if (!openedBy || !courseId)
            return 'false';

        var gr = new GlideRecord('x_752538_course_enrollment'); 
        gr.addQuery('opened_by', openedBy); 
        gr.addQuery('course', courseId);    
        gr.addQuery('state', 3);           
        gr.query();

        var count = 0;
        while (gr.next()) {
            count++;
        }

        return (count >= 3) ? 'true' : 'false';
    },

    type: 'CheckCourseEnrollmentLimit'
});
